"""Shared constant assets: no site data."""

ALERT_JS = "/* Device status is reconciled with the browser; no permission prompt on load. */\n(()=>{\n const root=document.getElementById('approval-alerts');if(!root)return;\n const line=root.querySelector('[data-alert-status]'),button=root.querySelector('[data-alert-toggle]'),error=root.querySelector('[data-alert-error]');\n let saved=root.dataset.device||'',expected=root.dataset.fingerprint||'',enabled=false,registration;\n const fingerprint=async(sub)=>{const p=sub.toJSON(),text=[new URL(p.endpoint).href,p.keys.p256dh,p.keys.auth].join('\\n'),bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)));return btoa(String.fromCharCode(...bytes)).replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=+$/g,'');};\n const deviceLabel=()=>{const ua=navigator.userAgent||'';const platform=/iPhone|iPod/.test(ua)?'iPhone':/iPad/.test(ua)||(/Macintosh/.test(ua)&&navigator.maxTouchPoints>1)?'iPad':/Android/.test(ua)?'Android':/Macintosh|Mac OS X/.test(ua)?'Mac':/Windows/.test(ua)?'Windows':'';const browser=/Edg(?:e|A|iOS)?\\//.test(ua)?'Edge':/Firefox\\/|FxiOS\\//.test(ua)?'Firefox':/Chrome\\/|CriOS\\//.test(ua)?'Chrome':/Safari\\//.test(ua)?'Safari':'';return platform&&browser?platform+' '+browser:'Browser';};\n const request=async(path,data)=>{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF':root.dataset.csrf},body:JSON.stringify(data)});if(!r.ok)throw Error('Alerts could not be changed. Reload this page and try again.');return r.json();};\n const status=async()=>{registration=await navigator.serviceWorker.getRegistration('/');const sub=await registration?.pushManager.getSubscription();enabled=!!saved&&!!sub&&Notification.permission==='granted'&&expected===await fingerprint(sub);line.textContent=enabled?'Alerts are on for this device':'Alerts are off for this device';button.textContent=enabled?'Turn alerts off':'Turn alerts on';};\n if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window)){line.textContent='Alerts are off for this device';button.disabled=true;error.hidden=false;error.textContent='This browser does not support alerts here. On iPhone use iOS 16.4 or later: Share → Add to Home Screen → open from the icon → turn alerts on.';return;}\n status().catch(()=>{line.textContent='Alerts are off for this device';});\n button.addEventListener('click',async()=>{\n  button.disabled=true;error.hidden=true;\n  try{\n   if(enabled){await request('/review/alerts/remove',{id:saved});saved='';expected='';const sub=await registration?.pushManager.getSubscription();if(sub)await sub.unsubscribe();}\n   else{\n    const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Alerts are off. You can change notification permission in your browser settings.');\n    const response=await fetch('/review/alerts/key');if(!response.ok)throw Error('Sign in again before turning alerts on.');const {public_key}=await response.json();\n    registration=await navigator.serviceWorker.register('/sw.js',{scope:'/'});await navigator.serviceWorker.ready;\n    const old=await registration.pushManager.getSubscription();if(old)await old.unsubscribe();\n    const key=Uint8Array.from(atob(public_key.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-public_key.length%4)%4)),c=>c.charCodeAt(0));\n    const sub=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});\n    try{const result=await request('/review/alerts/subscribe',{...sub.toJSON(),label:deviceLabel()});saved=result.id;expected=await fingerprint(sub);}catch(e){await sub.unsubscribe().catch(()=>{});throw e;}\n   }\n   await status();\n  }catch(e){error.hidden=false;error.textContent=e.message;await status().catch(()=>{});}finally{button.disabled=false;}\n });\n})();\n"
SW_JS = "/* Constant notification handler: no page cache and no fetch interception. */\nself.addEventListener('push',event=>{\n event.waitUntil((async()=>{\n  let p;try{p=event.data.json();}catch{return;}\n  if(!p||Object.keys(p).sort().join(',')!=='message,title,url'||p.message!=='Your site has a change waiting for you'||typeof p.title!=='string'||typeof p.url!=='string'||p.title.length>160)return;\n  let u;try{u=new URL(p.url);}catch{return;}\n  if(u.origin!==self.location.origin||u.pathname!=='/review'||u.search||u.hash)return;\n  await self.registration.showNotification(p.title,{body:p.message,data:{url:self.location.origin+'/review'}});\n })());\n});\nself.addEventListener('notificationclick',event=>{\n event.notification.close();\n event.waitUntil((async()=>{\n  const target=self.location.origin+'/review';\n  try{\n   const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});\n   const sameOrigin=windows.filter(c=>new URL(c.url).origin===self.location.origin);\n   let client=sameOrigin.find(c=>c.focused)||sameOrigin[0];\n   if(client){\n    if(client.url!==target)client=await client.navigate(target);\n    if(client){await client.focus();return;}\n   }\n  }catch{}\n  await self.clients.openWindow(target);\n })());\n});\n"
